package cart

// Line is one product in the cart.
type Line struct {
	SKU       string
	UnitCents int64
	Quantity  int
}

// Cart holds the shopper's lines.
type Cart struct {
	Lines []Line
}

// Total returns the sum of every line's unit price times quantity.
func (c *Cart) Total() int64 {
	var total int64
	for _, line := range c.Lines {
		total += line.UnitCents * int64(line.Quantity)
	}
	return total
}
